const pantryInteriorPages={pantry:0,fridge:0};
function interiorPage(items,page){const count=Math.max(1,Math.ceil(items.length/6)),index=Math.max(0,Math.min(count-1,page));return {items:items.slice(index*6,index*6+6),index,count}}
function changeInteriorShelf(kind,delta){pantryInteriorPages[kind]=Math.max(0,pantryInteriorPages[kind]+delta);render()}
function interiorProduce(batch){const reserved=Number(batch.reserved_grams)||0,expired=batch.expires_at&&Date.parse(batch.expires_at)<=Date.now();return `<button class="interior-produce ${expired?'interior-expired':''}" onclick="${batch.is_demo?`demoStoragePassport('${batch.id}')`:`showPassport('${batch.id}')`}" aria-label="${esc(batch.crop)} · ${storageKg(batch.balance_grams)}${expired?' · срок истёк':''} · паспорт партии" title="${esc(batch.crop)} · ${storageKg(batch.balance_grams)}${reserved?' · резерв '+storageKg(reserved):''}"><span class="interior-food" aria-hidden="true"><i>${storageCropIcon(batch.crop)}</i><i>${storageCropIcon(batch.crop)}</i><i>${storageCropIcon(batch.crop)}</i></span><span class="interior-tag"><b>${esc(batch.crop)}</b><strong>${storageKg(batch.balance_grams)}</strong>${expired?'<small>Нужен осмотр</small>':reserved?`<small>Резерв ${storageKg(reserved)}</small>`:''}</span></button>`}
function interiorZone(items,kind){const page=interiorPage(items,pantryInteriorPages[kind]);pantryInteriorPages[kind]=page.index;return `<section class="interior-inventory interior-${kind}" aria-label="${kind==='pantry'?'Кладовая':'Холодильник'}">${page.items.map(interiorProduce).join('')}${!items.length?'<p class="interior-empty">Пока пусто</p>':''}</section>`}
function interiorPager(items,kind){const page=interiorPage(items,pantryInteriorPages[kind]);return `<div class="interior-pager"><b>${kind==='pantry'?'Кладовая':'Холодильник'}</b><span>${storageKg(items.reduce((s,b)=>s+Number(b.balance_grams),0))}</span>${page.count>1?`<div><button aria-label="Предыдущие партии ${kind==='pantry'?'кладовой':'холодильника'}" ${page.index===0?'disabled':''} onclick="changeInteriorShelf('${kind}',-1)">←</button><small>${page.index+1} / ${page.count}</small><button aria-label="Следующие партии ${kind==='pantry'?'кладовой':'холодильника'}" ${page.index===page.count-1?'disabled':''} onclick="changeInteriorShelf('${kind}',1)">→</button></div>`:''}</div>`}
const beforeInteriorWarehouse=warehousePage;
warehousePage=function(){if(!account)return beforeInteriorWarehouse();const city=selectedFarmCity(),demo=isStorageDemo(),source=demo?demoStorageBatches():batchData,batches=source.filter(b=>Number(b.balance_grams)>0&&(!b.city_id||b.city_id===city)),pantry=batches.filter(b=>storageBatchGroup(b)==='pantry'),fridge=batches.filter(b=>storageBatchGroup(b)==='fridge'),waiting=batches.filter(b=>storageBatchGroup(b)==='receiving');return `<section class="pantry-experience"><div class="pantry-demo-switch"><span>${demo?'Пример: полгода игры · тестовые запасы':'Ваш настоящий урожай'}</span><button type="button" onclick="toggleStorageDemo()">${demo?'Показать мой урожай':'Посмотреть заполненный склад'}</button></div><div class="pantry-room-stage"><img class="pantry-room-background" src="art/interiors/pantry-room-v1.jpg" alt="Интерьер кладовой: деревянные стеллажи слева, стеклянный холодильник справа" fetchpriority="high"><div class="pantry-room-hud"><a href="#home">← Хозяйство</a><div><h1>Мой склад</h1><small>${esc(neighborCity(city)?.name||'')}</small></div></div>${interiorZone(pantry,'pantry')}${interiorZone(fridge,'fridge')}<p class="pantry-room-hint">Нажмите на урожай, чтобы открыть паспорт</p></div><div class="interior-stock-summary">${interiorPager(pantry,'pantry')}${interiorPager(fridge,'fridge')}</div>${waiting.length?`<section class="storage-receiving"><h2>🧺 Ожидает размещения</h2><p>Ферма должна подтвердить место хранения.</p><div class="storage-receiving-crates">${waiting.map(storageCrate).join('')}</div></section>`:''}<div class="storage-room-actions">${demo?'<button class="btn" onclick="toggleStorageDemo()">Перейти к своему урожаю</button>':'<button class="btn" onclick="basketForm()">Собрать корзину домой</button>'}<a class="btn light" href="#lifecycle">Хранение и доставка</a><button class="btn light" onclick="newBatch()">Записать сбор</button></div><p class="interior-note">${demo?'Демонстрационные запасы не продаются и не отправляются.':'На полках — фактический остаток партий, включая резерв.'} Сроки и условия — в паспорте урожая. Оформление комнаты иллюстративное.</p></section>`};

let storageDemoOverride=null;
function isStorageDemo(){if(storageDemoOverride!==null)return storageDemoOverride;try{const pref=localStorage.getItem('pantry-demo:'+account?.id);if(pref!==null)return pref==='on'}catch{}return account?.id==='bb593621-308a-47d4-bed2-c51baf7038cb'&&batchData.length===0}
function toggleStorageDemo(){storageDemoOverride=!isStorageDemo();try{localStorage.setItem('pantry-demo:'+account?.id,storageDemoOverride?'on':'off')}catch{}render()}
function demoStorageBatches(){return [['Картофель',42000,'pantry'],['Лук',12500,'pantry'],['Тыква',18000,'pantry'],['Свёкла',8500,'pantry'],['Чеснок',2300,'pantry'],['Кабачки',7600,'pantry'],['Морковь',5000,'fridge'],['Томаты',8400,'fridge'],['Огурцы',6200,'fridge'],['Перец',3700,'fridge'],['Баклажаны',4600,'fridge'],['Клубника',1800,'fridge']].map(([crop,grams,kind],i)=>({id:'demo-stock-'+i,crop,balance_grams:grams,reserved_grams:i===7?1400:0,verified:true,storage_kind:kind,city_id:selectedFarmCity(),is_demo:true}))}
function demoStoragePassport(id){const b=demoStorageBatches().find(x=>x.id===id);if(!b)return;modalForm('Пример запаса: '+esc(b.crop),`<p><b>Демонстрационный урожай · полгода игры</b></p><p>${esc(b.crop)} · ${storageKg(b.balance_grams)}</p><p>Место: ${b.storage_kind==='pantry'?'кладовая':'холодильник'}.</p><p>Эта партия показывает, как выглядит наполненный склад. Она не относится к реальному урожаю, не продаётся и не отправляется.</p><button type="button" class="btn" onclick="modal.close()">Вернуться на склад</button>`,()=>{})}
